//===================================================
//                                    Send and Receive 
//		Empty send string means receive only
//		Timeout set to a negative value means send only
//===================================================

CASE SdRd_Step OF

	0: 	//Init
		Done:=FALSE;
		ErrID:=WORD#0;
		SktTCPSend_Inst(	Execute	:=FALSE,
									SendDat:=Send_Data[0]);
		SktTCPRcv_Inst(	Execute	:=FALSE ,
					   				RcvDat:=Recv_Data[0]);
		SktClearBuf_Inst( Execute	:=FALSE);
		Str_Resp:='';
		IF Str_Send='' THEN SdRd_Step:=3; // No data to send -> receive only, don't clear the buffer
		ELSE 	
			SdRd_Step:=1;
		END_IF;
		
	1:  // Clear buffer ------------------------------------------------------
		SktClearBuf_inst( Execute	:=TRUE, 
           							Socket		:=TCP_Socket);   						
  
       IF (SktClearBuf_inst.Done=TRUE) THEN 
		   SdRd_Step						:=2;        			 // Normal end 
       ELSIF (SktClearBuf_inst.Error=TRUE) THEN 
		   SdRd_Step						:=4;       			// Error end 
       END_IF; 

	2: // Send Request ------------------------------------------------------

		Length									:= StringToAry(Str_Send,Send_Data[0]);
		SktTCPSend_Inst(	Execute	:=TRUE,															// --> send request
							Socket				:=TCP_Socket,
							SendDat			:=Send_Data[0],
							Size					:=Length);
				IF (SktTCPSend_Inst.Done) THEN
					IF Timeout > 0 THEN
						SdRd_Step			:=3;
					ELSE
						SdRd_Step			:=4;
					END_IF;
				ELSIF (SktTCPSend_Inst.Error) THEN
					ErrID:=SktTCPSend_Inst.ErrorID;
					SdRd_Step				:=4;
				END_IF;	
		
	3: // Receive response -----------------------------------------------------
			Clear(Recv_Data);			// Clear receive array
														
			SktTCPRcv_Inst(Execute	:=TRUE,
						Socket					:=TCP_Socket,
						Timeout				:=Timeout,														// Timeout default 1s
						Size						:=UINT#1024,
						RcvDat					:= Recv_Data[0]);	
					IF SktTCPRcv_Inst.Done THEN
							Str_Resp			:= AryToString(Recv_Data[0],SktTCPRcv_Inst.RcvSize);	
							SdRd_Step		:=INT#4;
					ELSIF SktTCPRcv_Inst.Error THEN
							ErrID					:=SktTCPRcv_Inst.ErrorID;
							SdRd_Step		:=INT#4;
					END_IF;
	
	4: // end 
	     	Done								:=TRUE;
		 	SdRd_Step						:=INT#0;
		 
END_CASE;
